        let local_start: DateTime<Local> = self.start.with_timezone(&Local);
        let time_str = match self.stop {
            Some(stop) => {
                let local_stop: DateTime<Local> = stop.with_timezone(&Local);
                let cross_day = local_stop.date_naive() != local_start.date_naive();
                if cross_day {
                    format!(
                        "{} ~ {}",
                        local_start.format("%Y-%m-%d %H:%M"),
                        local_stop.format("%m-%d %H:%M")
                    )
                } else {
                    format!(
                        "{}~{}",
                        local_start.format("%Y-%m-%d %H:%M"),
                        local_stop.format("%H:%M")
                    )
                }
            }
            None => format!("{}~…", local_start.format("%Y-%m-%d %H:%M")),
        };
        let summary = format!(
            //{id} {date HH:MM–HH:MM} {$/space} [{duration}]{running indicator/space} – {description}{@project} {#tags}
            "{} {} {} [{}]{} –  {}{} {}",
            self.id,
            time_str,
            if self.billable {
                "$".green().bold().to_string()
            } else {
                " ".to_string()
            },
            if self.is_running() {
                self.get_duration_hmmss().green().bold()
            } else {
                self.get_duration_hmmss().normal()
            },
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(",");
        let url = format!(
            "{}/workspaces/{}/time_entries/{}",
            self.base_url, workspace_id, ids
        );
        self.patch::<Value, Value>(url, &patch).await
    }

    async fn get_time_entries_filtered(
        &self,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<Vec<TimeEntry>> {
        let (network_entries, network_projects, network_tasks, network_clients) = tokio::join!(
            self.get_time_entries(since.as_deref(), until.as_deref()),
            self.get_projects(),
            self.get_tasks(),
            self.get_clients(),
        );

        let clients: HashMap<i64, crate::models::Client> = network_clients
            .unwrap_or_default()
            .into_iter()
            .map(|c| {
                (
                    c.id,
                    crate::models::Client {
                        id: c.id,
                        name: c.name,
                        workspace_id: c.wid,
                        archived: c.archived,
                    },
                )
            })
            .collect();

        let projects: HashMap<i64, Project> = network_projects
            .unwrap_or_default()

