        *totals.entry(name).or_default() += entry.duration;
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(name_a, seconds_a), (name_b, seconds_b)| {
        seconds_b.cmp(seconds_a).then_with(|| name_a.cmp(name_b))
    });
    totals
}

fn print_stats(entries: &[TimeEntry]) {
    let totals = project_totals(entries);
    let total_seconds: i64 = totals.iter().map(|(_, seconds)| seconds).sum();

    for (name, seconds) in totals {
        println!("{}  {}", utilities::format_duration_compact(seconds), name);
    }
    println!("{}  Total", utilities::format_duration_compact(total_seconds));
}

