use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use serde::Serialize;
use std::collections::HashMap;

pub struct StatsCommand;

#[derive(Serialize)]
struct StatsOutput {
    groups: Vec<StatsGroup>,
    total_seconds: i64,
}

#[derive(Serialize)]
struct StatsGroup {
    project: String,
    seconds: i64,
}

impl StatsCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
        json: bool,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        if json {
            print_json(&entries);
        } else {
            print_stats(&entries);
        }
        Ok(())
    }
}

fn project_totals(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut totals = HashMap::<String, i64>::new();
    for entry in entries.iter().filter(|entry| entry.duration >= 0) {
        let name = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| "No Project".to_string());
        *totals.entry(name).or_default() += entry.duration;
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(name_a, seconds_a), (name_b, seconds_b)| {
        seconds_b.cmp(seconds_a).then_with(|| name_a.cmp(name_b))
    });
    totals
}

fn print_stats(entries: &[TimeEntry]) {
    let totals = project_totals(entries);
    let total_seconds: i64 = totals.iter().map(|(_, seconds)| seconds).sum();

    for (name, seconds) in totals {
        println!("{}  {}", utilities::format_duration_compact(seconds), name);
    }
    println!(
        "{}  Total",
        utilities::format_duration_compact(total_seconds)
    );
}

fn print_json(entries: &[TimeEntry]) {
    let totals = project_totals(entries);
    let output = StatsOutput {
        total_seconds: totals.iter().map(|(_, seconds)| seconds).sum(),
        groups: totals
            .into_iter()
            .map(|(project, seconds)| StatsGroup { project, seconds })
            .collect(),
    };
    println!("{}", serde_json::to_string(&output).expect("failed to serialize stats"));
}

